function para_hamming_quant(output_dir)
%PARA_HAMMING_QUANT Generate apodization coefficient JSON.
if nargin < 1 || isempty(output_dir)
    output_dir = default_config_dir();
end

hamming_win = hamming(64);
hamming_words = uint32(round(hamming_win * (2^8 - 1)));

write_bram_json( ...
    output_dir, ...
    'hamming_default.json', ...
    'Hamming apodization coefficients generated by para_hamming_quant.m', ...
    {'hamming'}, ...
    {hamming_words});
end
